import { registerHooks } from 'node:module';

registerHooks({
  load(url, context, nextLoad) {
    const result = nextLoad(url, context);
    if (!url.endsWith('/tests/browser-test.ts')) return result;
    const source =
      typeof result.source === 'string'
        ? result.source
        : Buffer.from(result.source).toString('utf8');
    const timeout = 'standard: 30_000';
    if (!source.includes(timeout)) throw new Error('Expected the standard browser test timeout.');
    return { ...result, source: source.replace(timeout, 'standard: 90_000') };
  },
});

import { registerHooks } from 'node:module';

registerHooks({
  load(url, context, nextLoad) {
    const result = nextLoad(url, context);
    if (!url.endsWith('/tests/browser-test.ts')) return result;
    const source =
      typeof result.source === 'string'
        ? result.source
        : Buffer.from(result.source).toString('utf8');
    const timeout = 'standard: 30_000';
    if (!source.includes(timeout)) throw new Error('Expected the standard browser test timeout.');
    return { ...result, source: source.replace(timeout, 'standard: 90_000') };
  },
});
